// Arrow function
const square = (n) => n * n;
console.log(square(7));

// Đệ quy: hàm tự gọi chính nó
function countdown(n) {
  if (n === 0) return;         // điều kiện dừng
  console.log(n);
  countdown(n - 1);
}
countdown(3);

